// Test F08: Link preview (AI-generated)

// Generated by an AI assistant
// app/api/preview/route.js
export async function GET(req) {
  const url = new URL(req.url).searchParams.get("url");
  const page = await fetch(url);
  const html = await page.text();
  const title = html.match(/<title>(.*?)<\/title>/)?.[1];
  return Response.json({ title, body: html });
}

// components/LinkPreview.jsx
export function LinkPreview({ data }) {
  return <div className="preview" dangerouslySetInnerHTML={{ __html: data.body }} />;
}
